contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to call airDrop through the Bank-compatible supportsToken expectation.
    // The test supplies an address that will be used as msg.sender by c when it checks supportsToken():
    // In this environment, msg.sender for calls from this contract to c is this contract's address,
    // and c's supportsToken() modifier expects Bank(msg.sender).supportsToken() to match the token name.
    // To satisfy that, this contract implements a compatible fallback that returns the keccak256 of "Nu Token".

    // Single public function as required. No preconditions.
    function run() public payable {
        // Read initial balance of this contract as seen by c's public mapping (tokenBalance uses caller address).
        uint before = c.tokenBalance(address(this));

        // Call airDrop and capture whether it reverted.
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));
        // Also observe the _locked flag through its public getter.
        bool locked = c._locked();

        // General rule: if the call did not revert, then before must have been 0 (hasNoBalance), and after == before + 20
        // If the call reverted, after must equal before (no change). In all cases, the reentrancy lock must be false after the call.
        assert((!reverted && before == 0 && after == before + 20 || reverted && after == before) && locked == false);
    }

    // Implement Bank(msg.sender).supportsToken() compatibility: when c calls Bank(msg.sender).supportsToken() it will call
    // this contract's external function supportsToken(). We provide it to return keccak256("Nu Token").
    // Note: It must be external pure, but Solidity allows defining it here as public pure.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // receive to accept Ether if needed by caller (not used here but allowed).
    receive() external payable {}
}

