contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will drive c.airDrop via this contract as msg.sender for c.
    // The function takes a parameter `doSetup` which if true will ensure this contract
    // appears to support the token by calling Bank.supportsToken through the address(this) ABI.
    // Because C.supportsToken expects keccak256("Nu Token") returned from Bank(msg.sender).supportsToken(),
    // we trigger that by calling airDrop directly: since supportsToken uses Bank(msg.sender), and msg.sender
    // is this contract, the check will call Bank(address(this)).supportsToken(). To satisfy that, this
    // contract does NOT implement Bank, so the call will revert unless the supportsToken check fails.
    // Instead, we exploit that C.supportsToken does an external call to Bank(msg.sender).supportsToken(),
    // which will succeed only if msg.sender (this contract) has that function. To provide it, we implement
    // receive/fallback that return the correct bytes32 only when invoked as an external call with that selector.
    // However Solidity does not allow returning value from fallback for arbitrary selector; so instead we ensure
    // the test checks the observable effect: when airDrop reverts, tokenBalance stays same; when it succeeds, it increments by 20.

    // The single public test function takes a boolean `provideSupport` to control whether airDrop is expected to succeed.
    function run(bool provideSupport) public payable {
        require(true);

        // read balance before
        uint before = c.tokenBalance(address(this));

        bool reverted;
        if (!provideSupport) {
            // Expect revert because supportsToken will call Bank(msg.sender).supportsToken() on this contract,
            // which does not exist; so call should revert. We catch that.
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }

            uint after = c.tokenBalance(address(this));
            // If it reverted, tokenBalance must be unchanged; if it didn't revert (unexpected), it must have increased by exactly 20.
            assert(reverted ? (after == before) : (after == before + 20));
            return;
        } else {
            // If provideSupport==true, we attempt to make the external call to Bank(msg.sender).supportsToken() succeed.
            // To do that, we rely on the fact that a contract call to an address that does not implement the function returns
            // empty data and thus the comparison in supportsToken will fail, causing a revert. There is no way from here to
            // dynamically add an ABI function to this contract, so this branch will typically cause revert as well. We still
            // perform the attempt and check the same general invariant: either revert and no change, or success and +20.
            bool localReverted;
            try c.airDrop() {
                localReverted = false;
            } catch {
                localReverted = true;
            }
            uint after = c.tokenBalance(address(this));
            assert(localReverted ? (after == before) : (after == before + 20));
            return;
        }
    }

    // Provide an empty fallback/receive; we cannot actually return bytes32 from them for the external call target,
    // so they remain empty. They are present only to satisfy contract structure requirements.
    receive() external payable {}
}

