contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an address parameter representing msg.sender for c calls
    // but note: calls to c will have msg.sender = address(this) (the test contract), so
    // to exercise the supportsToken modifier we deploy a Bank-like helper by passing its address
    // through a parameter: the supportsToken modifier uses Bank(msg.sender), so msg.sender must
    // be a contract exposing supportsToken that returns keccak256("Nu Token").
    // However msg.sender for calls from this contract is this contract's address; thus the test
    // accepts a parameter `bytes32 supportsSig` to emulate correct or incorrect supportsToken via
    // the test contract's receive/fallback returning that value when c calls Bank(msg.sender).supportsToken().

    // The test uses an input flag `shouldMatch` to indicate whether the external supportsToken
    // should match the required keccak256("Nu Token"). If shouldMatch is true, the call to airDrop
    // should not revert due to supportsToken or hasNoBalance and should increase tokenBalance by 20.

    // NOTE: Solidity does not let us respond to external calls with custom return data from this contract
    // without implementing a function. But modifiers call Bank(msg.sender).supportsToken(), which is an
    // external call to msg.sender (this contract). Therefore we implement a fallback that returns
    // either the matching keccak256("Nu Token") or some other value depending on a stored flag.

    bool private returnMatch;

    function run(bool shouldMatch) public payable {
        // set the behavior for supportsToken() when c calls back to msg.sender
        returnMatch = shouldMatch;

        // read the before balance (tokenBalance is public getter)
        uint before = c.tokenBalance(address(this));

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // General rule asserted:
        // If the call reverted then after equals before (no state change observable).
        // Otherwise (didn't revert) then before must have been zero and after == before + 20.
        assert(reverted ? (after == before) : (before == 0 && after == before + 20));
    }

    // When C calls Bank(msg.sender).supportsToken(), it will call this contract.
    // We implement supportsToken() as an external function selector handler via fallback,
    // returning the keccak256("Nu Token") when returnMatch is true, otherwise some other value.
    fallback() external payable returns (bytes32) {
        // Determine if the call is expecting a bytes32 return (supportsToken) by calldata length
        // The selector for supportsToken() is bytes4(keccak256("supportsToken()")); but we don't
        // need to branch on selector; simply return appropriate 32 bytes for any call.
        bytes32 v = returnMatch ? keccak256(abi.encodePacked("Nu Token")) : keccak256(abi.encodePacked("Other"));
        assembly {
            // return the 32-byte word at memory location of v
            let ptr := mload(0x40)
            mstore(ptr, v)
            return(ptr, 32)
        }
    }

    receive() external payable {}
}

