contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address parameter that will be used by the Bank contract check via msg.sender in C.supportsToken.
    // However, since C.supportsToken compares keccak256("Nu Token") to Bank(msg.sender).supportsToken(),
    // and msg.sender inside that modifier will be the address of this test contract, the Bank used is the test's address.
    // To satisfy that, we provide a helper receive to return the correct bytes32 from supportsToken when C calls it.

    // We implement the required external function supportsToken() so that when C calls Bank(msg.sender).supportsToken()
    // (where msg.sender is this contract), it returns keccak256("Nu Token"). This makes the supportsToken modifier pass.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // Make the test payable in case some path would require sending Ether (not needed here, but allowed by template).
    function run(address caller) public payable {
        require(caller != address(0));

        // Read the initial balance for this test contract (which will be msg.sender as seen by C).
        uint before = c.tokenBalance(address(this));

        // Ensure precondition for C.airDrop: hasNoBalance requires tokenBalance[msg.sender]==0.
